def load(d): return [c for p in sorted(d.glob('*.json')) for c in json.loads(p.read_text()).get('cases',[])]
def check(v=VALID,i=INVALID):
 f=[]; vc=load(v); ic=load(i); av=[c.get('name') for c in vc]; ai={c.get('name'):sorted(set(c.get('expected_error_ids') or [])) for c in ic}
 if av!=EXPECTED_VALID: f.append(f'valid case order/name mismatch: {av}')
 if ai!=EXPECTED_INVALID:
  f.append(f'invalid case registry mismatch: missing={sorted(set(EXPECTED_INVALID)-set(ai))} extra={sorted(set(ai)-set(EXPECTED_INVALID))}')
  for n in sorted(set(EXPECTED_INVALID)&set(ai)):
   if ai[n]!=EXPECTED_INVALID[n]: f.append(f'{n} expected IDs {EXPECTED_INVALID[n]} found {ai[n]}')
 return f
def self_test():
 with tempfile.TemporaryDirectory() as td:
  root=Path(td); v=root/'valid'; i=root/'invalid'; shutil.copytree(VALID,v); shutil.copytree(INVALID,i); p=sorted(i.glob('*.json'))[0]; d=json.loads(p.read_text()); d['cases'][0]['expected_error_ids']=['CTX_OVL_E_UNRELATED']; p.write_text(json.dumps(d,indent=2)+'\n')
